from playwright.sync_api import sync_playwright

pages = [
    'https://127.0.0.1:5110/nexifynewweb/energy.php',
    'https://127.0.0.1:5110/nexifynewweb/ecosystem.php',
    'https://127.0.0.1:5110/nexifynewweb/partners.php',
    'https://127.0.0.1:5110/nexifynewweb/gemi.php',
    'https://127.0.0.1:5110/nexifynewweb/faq.php',
    'https://127.0.0.1:5110/nexifynewweb/contact.php',
]

with sync_playwright() as p:
    browser = p.chromium.launch(headless=True)
    context = browser.new_context(ignore_https_errors=True)
    page = context.new_page()
    page.set_viewport_size({'width': 1920, 'height': 1080})

    for url in pages:
        name = url.split('/')[-1].replace('.php','')
        page.goto(url)
        page.wait_for_load_state('domcontentloaded')
        page.wait_for_timeout(1000)

        # Check for pillar buttons
        info = page.evaluate('''() => {
            const pillars = document.querySelectorAll(\".pillar\");
            return Array.from(pillars).map((p, i) => {
                const btn = p.querySelector(\".btn\");
                const pRect = p.getBoundingClientRect();
                const bRect = btn ? btn.getBoundingClientRect() : null;
                return {
                    pillar: i+1,
                    height: pRect.height,
                    btnTop: bRect ? Math.round(bRect.top) : null,
                };
            });
        }''')
        if info:
            print(f\"--- {name} PILLARS ---\")
            for item in info:
                print(f\"  Pillar {item['pillar']}: h={item['height']}, btnTop={item['btnTop']}\")

        # Check general CTAs
        btns = page.evaluate('''() => {
            const btns = document.querySelectorAll(\".btn:not(.nav-cta):not([data-testid=\\\"cookie-accept\\\"])\");
            return Array.from(btns).map(b => ({
                text: b.innerText.trim().substring(0, 30),
                top: Math.round(b.getBoundingClientRect().top),
                height: Math.round(b.getBoundingClientRect().height),
                cls: b.className
            }));
        }''')
        print(f\"--- {name} ALL BTNS ---\")
        for b in btns:
            print(f\"  '{b['text']}' top={b['top']} h={b['height']}\")

    browser.close()
"

